const response = await fetch('https://api.capisum.com/v1/transactions/payout', {
  method: 'POST',
  headers: {
    Authorization: 'Bearer cps_your_key',
    'Content-Type': 'application/json',
    'X-Idempotency-Key': 'payout-order-123',
  },
  body: JSON.stringify({
    amount: '500000',
    currency: 'NGN',
    provider: 'fincra',
    destination: {
      type: 'bank_account',
      bank_id: 'ng.opay',
      account_number: '7068270185',
      account_name: 'Test Recipient',
    },
  }),
});
const { data } = await response.json();

